package com.oracle.banking.customer.dto;
import com.oracle.banking.customer.entity.CustomerProfile; import jakarta.validation.constraints.*;
public final class CustomerDtos {private CustomerDtos(){} public record Create(@NotBlank String userId,@NotBlank String fullName,@NotBlank @Email String email,@NotBlank @Pattern(regexp="^[+]?[0-9]{7,15}$") String phone){} public record Update(@NotBlank @Size(max=120) String fullName,@NotBlank @Pattern(regexp="^[+]?[0-9]{7,15}$") String phone,@Size(max=160) String addressLine1,@Size(max=160) String addressLine2,@Size(max=80) String city,@Size(max=80) String state,@Size(max=80) String country,@Size(max=20) String postalCode){} public record Response(String customerId,String userId,String fullName,String email,String phone,String addressLine1,String addressLine2,String city,String state,String country,String postalCode,String kycStatus,String profileStatus){public static Response from(CustomerProfile p){return new Response(p.getCustomerId(),p.getUserId(),p.getFullName(),p.getEmail(),p.getPhone(),p.getAddressLine1(),p.getAddressLine2(),p.getCity(),p.getState(),p.getCountry(),p.getPostalCode(),p.getKycStatus(),p.getProfileStatus());}}}
